import request from '../hooks/useHttp'

export function getKnowledgeList(params) {
  return request({
    url: '/knowledge/list',
    method: 'get',
    params
  })
}

export function createKnowledge(data) {
  return request({
    url: '/knowledge/create',
    method: 'post',
    data
  })
}

export function updateKnowledge(data) {
  return request({
    url: `/knowledge/update/${data.id}`,
    method: 'post',
    data
  })
}

export function deleteKnowledge(id) {
  return request({
    url: `/knowledge/delete/${id}`,
    method: 'delete'
  })
}

export function getKnowledgeFileList(params) {
  return request({
    url: `/knowledge/${params.id}/files`,
    method: 'get',
    params
  })
}

export function deleteKnowledgeFile(id) {
  return request({
    url: `/knowledge/file/${id}/delete`,
    method: 'delete'
  })
}

export function getFileDetail(id, responseType) {
  console.log('responseType_knowledge', responseType)
  return request({
    url: `/knowledge/file/${id}/detail`,
    method: 'post',
    responseType: responseType
  })
}

export function uploadFile(data) {
  return request({
    url: `/knowledge/update/${data.get('id')}/files`,
    method: 'post',
    data
  })
}

export function getKnowledgeSetting(id) {
  return request({
    url: `/knowledge/${id}/session`,
    method: 'get'
  })
}

export function getDBConfig(name) {
  return request({
    url: `/knowledge/config/${name}`,
    method: 'get'
  })
}

export function updateDBConfig(data) {
  return request({
    url: `/knowledge/config/${data.name}`,
    method: 'post',
    data
  })
}

export function getEmbedModels() {
  return request({
    url: `/models/download/embedding/list`,
    method: 'get'
  })
}

export function uploadLongCodeFile(data) {
  return request({
    url: `/longcode/upload`,
    method: 'post',
    data
  })
}

export function cleanLongCodeFile(data) {
  return request({
    url: `/longcode/clean`,
    method: 'post',
    data
  })
}

export function getFileChatConfig(params) {
  return request({
    url: '/knowledge/filechat/config',
    method: 'get',
    params
  })
}

export function updateFileChatConfig(data) {
  return request({
    url: '/knowledge/filechat/config',
    method: 'post',
    data
  })
}

export function getKbPluginSetting(data) {
  return request({
    url: `/knowledge/${data.kbId}/session/${data.sessionId}`,
    method: 'post',
    data
  })
}

export function updateKbPluginSetting(params, data) {
  return request({
    url: `/knowledge/${params.kbId}/session/${params.sessionId}/update `,
    method: 'post',
    data
  })
}

export function getDocChatEmbedModel(kbId) {
  return request({
    url: `/knowledge/${kbId}/current_embedding_info`,
    method: 'get'
  })
}

export function analysisKnowledgeFile(data) {
  return request({
    url: `/knowledge/file/${data.id}/analysis`,
    method: 'post',
    data
  })
}
